-- User.users_authorization_change_stamp: Turns every change to an account's access (tokenVersion, isActive, isDeleted) into an epoch-ms stamp in User.authorizationChangedAt, committed with the change: the backstop the AuthorizationChangeSweep reads.
DROP TRIGGER IF EXISTS users_authorization_change_stamp ON public."User";
CREATE TRIGGER users_authorization_change_stamp
  BEFORE UPDATE OF "tokenVersion", "isActive", "isDeleted" ON public."User"
  FOR EACH ROW
  EXECUTE FUNCTION app_stamp_authorization_change();

-- AuditLog.audit_trail_notify: Signals `audit_trail` once per request row, except reads of the audit log itself (viewing the log would otherwise make every open page refetch forever).
DROP TRIGGER IF EXISTS audit_trail_notify ON public."AuditLog";
CREATE TRIGGER audit_trail_notify
  AFTER INSERT ON public."AuditLog"
  FOR EACH ROW
  WHEN (NOT (NEW.method = 'GET' AND NEW.endpoint ~ '^/api/v[0-9]+/admin/(audit-|data-changes)'))
  EXECUTE FUNCTION public.audit_trail_notify();

-- DataChangeLog.audit_trail_notify: Signals `audit_trail` once per statement, so a bulk job signals once.
DROP TRIGGER IF EXISTS audit_trail_notify ON public."DataChangeLog";
CREATE TRIGGER audit_trail_notify
  AFTER INSERT ON public."DataChangeLog"
  FOR EACH STATEMENT
  EXECUTE FUNCTION public.audit_trail_notify();
